    {
      "@type": "FAQPage",
      "mainEntity": [

        {
          "@type": "Question",
          "name": "What is an air washer unit and how does it work?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "An air washer unit is an HVAC device that cools, cleans, and humidifies air using water. The air washer working principle involves passing air through water-saturated cooling pads where evaporation removes heat while water traps dust and particles. Unlike air conditioners, air washers use no refrigerants and consume 60-70% less electricity."
          }
        },

        {
          "@type": "Question",
          "name": "Where are air washer units commonly used?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Air washer units are used in pharmaceutical plants, food processing units, textile mills, plastic industries, poultry farms, commercial buildings (malls, auditoriums, banquet halls), hospitals, and manufacturing facilities. Any space requiring cooling with 100% fresh air is ideal."
          }
        },

        {
          "@type": "Question",
          "name": "What is the typical air washer unit price range?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "For a standard 10,000 CMH MS unit, expect ₹1.4 to ₹1.9 lakhs ex-Mumbai. SS 304 units for pharma applications cost ₹2.5 to ₹3.5 lakhs. Custom units are quoted based on specifications. Contact us for an exact price."
          }
        },

        {
          "@type": "Question",
          "name": "Can air washer units be customized for different capacity needs?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. We manufacture units from 500 CMH to 2,00,000 CMH. Every aspect is customizable – material, panel thickness, accessories, and dimensions. We design based on your specific requirements."
          }
        },
         {
          "@type": "Question",
          "name": "How much electricity does an air washer unit consume?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Much less than AC. A 10,000 CMH air washer unit typically consumes 3-5 kW compared to 15-20 kW for a similar capacity AC system. Actual consumption depends on motor efficiency and operating hours."
          }
        },
         {
          "@type": "Question",
          "name": "What maintenance does an air washer unit require?
",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Daily: Check water level. Weekly: Clean strainer, inspect pads. Monthly: Clean sump, check motor bearings. Yearly: Replace cooling pads if worn. AMC options available for hassle-free maintenance.
"
          }
        },
         {
          "@type": "Question",
          "name": "How long do cooling pads last?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Cellulose paper pads typically last 2-3 years with proper water quality. Hard water reduces pad life. We recommend using soft water and regular cleaning to maximize pad life."
          }
        },
         {
          "@type": "Question",
          "name": "Are Peter Air air washer units suitable for high-temperature areas?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Our units are designed for Indian conditions including Rajasthan (48°C+), coastal humidity, and dusty industrial environments."
          }
        },
         {
          "@type": "Question",
          "name": "Do you provide installation across India?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. We serve clients across India with on-site installation support. Major cities have dedicated service teams. Remote locations are covered by our partner network."
          }
        },
         {
          "@type": "Question",
          "name": "What warranty do you offer?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "1 year comprehensive warranty covering manufacturing defects, motor, blower, and electrical components. Extended warranty available with AMC."
          }
        },
         {
          "@type": "Question",
          "name": "Can I use an air washer unit in a cleanroom?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes, but with HEPA filtration add-on. For ISO-classified cleanrooms, we recommend our air shower and HEPA filter systems combined with the air washer for pre-conditioning."
          }
        }

